<?php require_once dirname(__DIR__).'/includes/functions.php';require_login();$uid=(int)user()['id'];$stmt=$con->prepare('SELECT id,data,created_at,is_read FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 10');$stmt->bind_param('i',$uid);$stmt->execute();$items=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt=$con->prepare('SELECT COUNT(*) n FROM notifications WHERE user_id=? AND is_read=0');$stmt->bind_param('i',$uid);$stmt->execute();$unread=(int)$stmt->get_result()->fetch_assoc()['n'];$stmt=$con->prepare('UPDATE notifications SET is_read=1 WHERE user_id=?');$stmt->bind_param('i',$uid);$stmt->execute();json_response(['ok'=>true,'unread'=>$unread,'items'=>$items]);
